rows = [[4]*28 for _ in range(23)]
zeros = {1:[4,13,19,25],2:[1,7,16,22],3:[11],4:[24],5:[2,9,14,21],7:[5,12,17],9:[9,19],10:[4,16],11:[1,13,22],12:[6],13:[3,10],14:[14,21,25],15:[7],16:[1,19],17:[10,15],18:[4,27],20:[2,17,21],21:[7,12]}
for r,cs in zeros.items():
 for c in cs: rows[r][c]=0
# Prototype is a 3x3 transparent cross: top-center 6; middle [3,9,5]; bottom-center 2.
rows[8][25]=6; rows[9][24:27]=[3,9,5]; rows[10][25]=2
# Copy, centered on each zero marker; painted motif cells overwrite the anchor with center color 9.
for r,cs in zeros.items():
 for c in cs:
  for dr,dc,color in [(-1,0,6),(0,-1,3),(0,0,9),(0,1,5),(1,0,2)]:
   rows[r+dr][c+dc]=color
assert len(rows)==23 and all(len(r)==28 for r in rows)
import json
print(json.dumps({'action':'submit','grid':rows},separators=(',',':')))

